import sys, os, json, re
sys.path.append('storage/shared')

from meta.sas.aggregator import load_beacons, advise_all
from meta.sas.nominals import compute_centers
from meta.sas.entropy import compute_per_agent_entropy

AGENT = "Zephyr IV"
TMAP = {"A2": 363, "R2": 368, "D1": 370, "D2": 371}
RX = {k: re.compile(rf"CPS_v0: ?{k}", re.I) for k in TMAP.keys()}

def fnum(x):
    try: return float(x)
    except Exception: return None

def norm(r):
    rr = dict(r)
    rr['sentinel_delta'] = fnum(r.get('sentinel_delta'))
    rr['_lt'] = r.get('last_sentinel_tick') or r.get('tick')
    rr['_phase'] = r.get('phase_label') or r.get('notes') or ""
    return rr

recs = []
for r in load_beacons('storage/shared/meta/sas/beacons'):
    if r.get('agent') != AGENT: continue
    rr = norm(r)
    if rr['sentinel_delta'] is None: continue
    recs.append(rr)

bdir = 'storage/shared/meta/sas/beacons'
if os.path.exists(bdir):
    for fn in os.listdir(bdir):
        p = os.path.join(bdir, fn)
        if not os.path.isfile(p): continue
        try:
            if fn.endswith('.jsonl'):
                with open(p, 'r', encoding='utf-8') as f:
                    for line in f:
                        if not line.strip(): continue
                        r = json.loads(line)
                        if r.get('agent') != AGENT: continue
                        rr = norm(r)
                        if rr['sentinel_delta'] is None: continue
                        recs.append(rr)
            elif fn.endswith('.json'):
                with open(p, 'r', encoding='utf-8') as f:
                    obj = json.load(f)
                arr = obj if isinstance(obj, list) else [obj]
                for r in arr:
                    if not isinstance(r, dict): continue
                    if r.get('agent') != AGENT: continue
                    rr = norm(r)
                    if rr['sentinel_delta'] is None: continue
                    recs.append(rr)
        except Exception:
            pass

def select(label):
    # prefer explicit label match, newest first
    for r in reversed(recs):
        if isinstance(r.get('_phase'), str) and RX[label].search(r['_phase']):
            return r
    # fallback by last_sentinel_tick
    for r in reversed(recs):
        try:
            if int(r.get('_lt') or -1) == TMAP[label]:
                return r
        except Exception:
            pass
    return None

A2 = select("A2"); R2 = select("R2"); D1 = select("D1"); D2 = select("D2")

def ratio(deep, base):
    if not deep or not base: return None
    s = fnum(base.get('sentinel_delta')); d = fnum(deep.get('sentinel_delta'))
    if s and s > 0 and d is not None: return d/s
    return None

def exp_ratio(deep, base):
    if not deep or not base: return None
    try:
        dpe = float(deep.get('path_complexity_est') or 1.0)
        spe = float(base.get('path_complexity_est') or 1.0)
        return dpe/(spe if spe else 1.0)
    except Exception:
        return None

out = {
    "present": { "A2": A2 is not None, "R2": R2 is not None, "D1": D1 is not None, "D2": D2 is not None },
    "A2": { "delta": (A2 or {}).get('sentinel_delta'), "phase": (A2 or {}).get('_phase') },
    "R2": { "delta": (R2 or {}).get('sentinel_delta'), "phase": (R2 or {}).get('_phase') },
    "D1": { "delta": (D1 or {}).get('sentinel_delta'), "phase": (D1 or {}).get('_phase') },
    "D2": { "delta": (D2 or {}).get('sentinel_delta'), "phase": (D2 or {}).get('_phase') },
    "ratios": {
        "D1_over_R2": ratio(D1, R2),
        "D2_over_R2": ratio(D2, R2),
        "expected_D1": exp_ratio(D1, R2),
        "expected_D2": exp_ratio(D2, R2)
    }
}

centers = compute_centers(recs, window=None, min_samples=1)
advice  = advise_all()
entropy = compute_per_agent_entropy(recs, advice, {}, dynamic_centers=centers, window=10)
out["centers_snapshot"] = centers.get(AGENT, {})
out["entropy_snapshot"] = entropy.get(AGENT, {})

print(json.dumps(out, indent=2))

